with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce01quh056', 'practice', 'Lecture B1 : quel cours de langue ?', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces quatre annonces, puis répondez aux questions.</p>', '<p><strong>Votre situation :</strong> vous voulez apprendre l''espagnol avec votre colocataire. Vous n''avez jamais étudié cette langue. Vous travaillez tous les deux la journée. Vous cherchez un cours le soir, pour débutants, en petit groupe (10 personnes au maximum), qui coûte moins de 250 € le trimestre.</p><p><strong>A. École Hola Madrid :</strong> cours le mardi et le jeudi, de 18 h 30 à 20 h. Niveaux intermédiaire et avancé uniquement. Groupes de 8 élèves. 220 € le trimestre.</p><p><strong>B. Association Puerta Abierta :</strong> pour les grands débutants, le samedi de 10 h à 12 h. Groupes de 6 personnes, ambiance conviviale. 150 € le trimestre.</p><p><strong>C. Centre Cervantes Plus :</strong> tous niveaux, y compris débutants. Le lundi de 19 h à 21 h. Classes de 15 à 20 élèves. 180 € le trimestre.</p><p><strong>D. Atelier Sol y Luna :</strong> cours pour débutants le mercredi de 19 h à 20 h 30. Groupes de 10 personnes au maximum. 240 € le trimestre, livre compris.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un trimestre (nom masculin) : ba tháng, một quý\n• un débutant (nom masculin) : người mới học\n• uniquement (adverbe) : chỉ\n• convivial (adjectif) : thân mật, vui vẻ\n• compris (adjectif) : đã bao gồm","explications":"• Đọc tiêu chí trước, rồi quét từng quảng cáo theo từng tiêu chí, không đọc kỹ từng chữ.\n• Chỉ một tài liệu đạt mọi tiêu chí. Thấy một chữ NON là bỏ tài liệu đó.","isPremium":true,"price":19000,"kyNang":"B1-CE-1","vong":"hoc","thuTu":4}'::jsonb, '2026-11-04T00:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub008', 'b1ce01quh056', 1, 'tableau', 'Pour chaque annonce, cochez OUI ou NON.', '{"colonnes":[{"id":"cmw0y9qub000","titre":"A"},{"id":"cmw0y9qub001","titre":"B"},{"id":"cmw0y9qub002","titre":"C"},{"id":"cmw0y9qub003","titre":"D"}],"criteres":[{"id":"rmw0y9qub004","texte":"Le cours a lieu le soir."},{"id":"rmw0y9qub005","texte":"Le cours accepte les débutants."},{"id":"rmw0y9qub006","texte":"Le groupe a 10 personnes au maximum."},{"id":"rmw0y9qub007","texte":"Le cours coûte moins de 250 € le trimestre."}]}'::jsonb, '{"answers":{"rmw0y9qub004_cmw0y9qub000":"OUI","rmw0y9qub004_cmw0y9qub001":"NON","rmw0y9qub004_cmw0y9qub002":"OUI","rmw0y9qub004_cmw0y9qub003":"OUI","rmw0y9qub005_cmw0y9qub000":"NON","rmw0y9qub005_cmw0y9qub001":"OUI","rmw0y9qub005_cmw0y9qub002":"OUI","rmw0y9qub005_cmw0y9qub003":"OUI","rmw0y9qub006_cmw0y9qub000":"OUI","rmw0y9qub006_cmw0y9qub001":"OUI","rmw0y9qub006_cmw0y9qub002":"NON","rmw0y9qub006_cmw0y9qub003":"OUI","rmw0y9qub007_cmw0y9qub000":"OUI","rmw0y9qub007_cmw0y9qub001":"OUI","rmw0y9qub007_cmw0y9qub002":"OUI","rmw0y9qub007_cmw0y9qub003":"OUI"}}'::jsonb, 'A: « niveaux intermédiaire et avancé uniquement ». B: « le samedi de 10 h à 12 h » là buổi sáng. C: « classes de 15 à 20 élèves ». D đạt cả bốn tiêu chí.'), ('qmw0y9qub009', 'b1ce01quh056', 2, 'qcm', 'Quel cours choisissez-vous ?', '{"options":["A. École Hola Madrid","C. Centre Cervantes Plus","D. Atelier Sol y Luna"]}'::jsonb, '{"answer":2}'::jsonb, 'Chỉ D có đủ OUI ở mọi tiêu chí: « cours pour débutants le mercredi de 19 h à 20 h 30 », « 10 personnes au maximum », « 240 € le trimestre ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce02quj057', 'practice', 'Lecture B1 : un job pour l''été', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces quatre offres d''emploi, puis répondez aux questions.</p>', '<p><strong>Votre situation :</strong> vous êtes étudiant ou étudiante et vous cherchez un travail pour tout l''été, en juillet et en août. Vous n''avez aucune expérience professionnelle. Vous voulez être logé sur place et travailler au moins 25 heures par semaine.</p><p><strong>A. Glacier Le Cornet, Nice :</strong> nous recrutons un vendeur ou une vendeuse du 15 juillet au 15 août, 30 heures par semaine. Expérience dans la vente demandée. Pas de logement.</p><p><strong>B. Ferme Dumas, Provence :</strong> cueillette de fruits en juillet et en août. Aucune expérience nécessaire. Chambre fournie à la ferme. 15 heures par semaine, le matin seulement.</p><p><strong>C. Camping Les Pins, Vendée :</strong> nous cherchons des animateurs du 1er juillet au 31 août. Débutants acceptés, formation sur place. 35 heures par semaine. Logement offert dans un mobil-home.</p><p><strong>D. Hôtel du Lac, Annecy :</strong> réceptionniste de juillet à fin août, 35 heures par semaine. Deux ans d''expérience exigés et anglais courant. Logement possible dans l''hôtel.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• recruter (verbe) : tuyển\n• la cueillette (nom féminin) : việc hái quả\n• fourni (adjectif) : được cấp\n• exigé (adjectif) : bắt buộc phải có\n• courant (adjectif) : (nói) trôi chảy","explications":"• Cẩn thận với ngày: « du 15 juillet au 15 août » không phải cả hè.\n• Débutants acceptés, aucune expérience nécessaire: hai cách nói cùng một ý.","isPremium":true,"price":19000,"kyNang":"B1-CE-1","vong":"hoc","thuTu":5}'::jsonb, '2026-11-04T00:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub00i', 'b1ce02quj057', 1, 'tableau', 'Pour chaque offre, cochez OUI ou NON.', '{"colonnes":[{"id":"cmw0y9qub00a","titre":"A"},{"id":"cmw0y9qub00b","titre":"B"},{"id":"cmw0y9qub00c","titre":"C"},{"id":"cmw0y9qub00d","titre":"D"}],"criteres":[{"id":"rmw0y9qub00e","texte":"Le travail dure tout l''été (juillet et août)."},{"id":"rmw0y9qub00f","texte":"Aucune expérience n''est demandée."},{"id":"rmw0y9qub00g","texte":"Un logement est proposé."},{"id":"rmw0y9qub00h","texte":"On travaille au moins 25 heures par semaine."}]}'::jsonb, '{"answers":{"rmw0y9qub00e_cmw0y9qub00a":"NON","rmw0y9qub00e_cmw0y9qub00b":"OUI","rmw0y9qub00e_cmw0y9qub00c":"OUI","rmw0y9qub00e_cmw0y9qub00d":"OUI","rmw0y9qub00f_cmw0y9qub00a":"NON","rmw0y9qub00f_cmw0y9qub00b":"OUI","rmw0y9qub00f_cmw0y9qub00c":"OUI","rmw0y9qub00f_cmw0y9qub00d":"NON","rmw0y9qub00g_cmw0y9qub00a":"NON","rmw0y9qub00g_cmw0y9qub00b":"OUI","rmw0y9qub00g_cmw0y9qub00c":"OUI","rmw0y9qub00g_cmw0y9qub00d":"OUI","rmw0y9qub00h_cmw0y9qub00a":"OUI","rmw0y9qub00h_cmw0y9qub00b":"NON","rmw0y9qub00h_cmw0y9qub00c":"OUI","rmw0y9qub00h_cmw0y9qub00d":"OUI"}}'::jsonb, 'A: chỉ « du 15 juillet au 15 août » và cần kinh nghiệm. B: chỉ « 15 heures par semaine ». D: « deux ans d''expérience exigés ». C đạt cả bốn tiêu chí.'), ('qmw0y9qub00j', 'b1ce02quj057', 2, 'qcm', 'Quelle offre choisissez-vous ?', '{"options":["B. Ferme Dumas","C. Camping Les Pins","D. Hôtel du Lac"]}'::jsonb, '{"answer":1}'::jsonb, 'C: « du 1er juillet au 31 août », « débutants acceptés », « logement offert », « 35 heures par semaine ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce03quj058', 'practice', 'Lecture B1 : un séjour à la montagne', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces quatre annonces, puis répondez aux questions.</p>', '<p><strong>Votre situation :</strong> vous partez une semaine à la montagne en février avec votre conjoint, vos deux enfants de 6 et 9 ans et votre chien. Vous voulez des activités pour les enfants, un logement à moins de 500 mètres des pistes de ski et un prix inférieur à 900 € la semaine.</p><p><strong>A. Chalet Edelweiss :</strong> chalet pour 5 personnes, à 200 mètres des pistes. Club enfants à partir de 4 ans au village. 850 € la semaine. Animaux non admis.</p><p><strong>B. Résidence Les Marmottes :</strong> appartements de 4 à 6 personnes, à 300 mètres des pistes. Garderie et jeux pour les 3 à 10 ans. Vos animaux sont les bienvenus. 780 € la semaine.</p><p><strong>C. Gîte du Berger :</strong> au calme, à 3 kilomètres des pistes, navette gratuite. Chiens acceptés. Idéal pour les familles, aire de jeux pour enfants. 600 € la semaine.</p><p><strong>D. Hôtel Le Sommet :</strong> au pied des pistes. Chiens acceptés. Cours de ski pour enfants dès 5 ans. 1 400 € la semaine pour quatre personnes.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• les pistes (nom féminin pluriel) : đường trượt tuyết\n• admis (adjectif) : được chấp nhận\n• une garderie (nom féminin) : nơi giữ trẻ\n• une navette (nom féminin) : xe đưa đón\n• au pied de (expression) : ngay chân (núi, dốc)","explications":"• « Au pied des pistes » nghĩa là sát đường trượt: vẫn tính dưới 500 m.\n• « Vos animaux sont les bienvenus » là cách nói lịch sự của « animaux acceptés ».","isPremium":true,"price":19000,"kyNang":"B1-CE-1","vong":"on","thuTu":6}'::jsonb, '2026-11-04T00:00:02.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub00s', 'b1ce03quj058', 1, 'tableau', 'Pour chaque annonce, cochez OUI ou NON.', '{"colonnes":[{"id":"cmw0y9qub00k","titre":"A"},{"id":"cmw0y9qub00l","titre":"B"},{"id":"cmw0y9qub00m","titre":"C"},{"id":"cmw0y9qub00n","titre":"D"}],"criteres":[{"id":"rmw0y9qub00o","texte":"Il y a des activités pour les enfants."},{"id":"rmw0y9qub00p","texte":"On peut venir avec un chien."},{"id":"rmw0y9qub00q","texte":"Le logement est à moins de 500 m des pistes."},{"id":"rmw0y9qub00r","texte":"La semaine coûte moins de 900 €."}]}'::jsonb, '{"answers":{"rmw0y9qub00o_cmw0y9qub00k":"OUI","rmw0y9qub00o_cmw0y9qub00l":"OUI","rmw0y9qub00o_cmw0y9qub00m":"OUI","rmw0y9qub00o_cmw0y9qub00n":"OUI","rmw0y9qub00p_cmw0y9qub00k":"NON","rmw0y9qub00p_cmw0y9qub00l":"OUI","rmw0y9qub00p_cmw0y9qub00m":"OUI","rmw0y9qub00p_cmw0y9qub00n":"OUI","rmw0y9qub00q_cmw0y9qub00k":"OUI","rmw0y9qub00q_cmw0y9qub00l":"OUI","rmw0y9qub00q_cmw0y9qub00m":"NON","rmw0y9qub00q_cmw0y9qub00n":"OUI","rmw0y9qub00r_cmw0y9qub00k":"OUI","rmw0y9qub00r_cmw0y9qub00l":"OUI","rmw0y9qub00r_cmw0y9qub00m":"OUI","rmw0y9qub00r_cmw0y9qub00n":"NON"}}'::jsonb, 'A: « animaux non admis ». C: « à 3 kilomètres des pistes ». D: « 1 400 € la semaine ». B đạt cả bốn tiêu chí.'), ('qmw0y9qub00t', 'b1ce03quj058', 2, 'qcm', 'Quel logement choisissez-vous ?', '{"options":["A. Chalet Edelweiss","B. Résidence Les Marmottes","C. Gîte du Berger"]}'::jsonb, '{"answer":1}'::jsonb, 'B: « à 300 mètres des pistes », « jeux pour les 3 à 10 ans », « vos animaux sont les bienvenus », « 780 € la semaine ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce04quj059', 'practice', 'Lecture B1 : choisissez le bon document', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces quatre documents, puis répondez aux questions.</p>', '<p><strong>Votre situation :</strong> vous voulez offrir un abonnement sportif à votre père, qui a 62 ans. Il veut des cours adaptés aux seniors, une salle ouverte avant 9 h du matin, une piscine et un parking gratuit.</p><p><strong>A. Forme Plus :</strong> ouvert tous les jours de 6 h à 22 h. Piscine couverte. Cours de gym douce réservés aux plus de 60 ans le mardi et le jeudi. Parking payant, 2 € de l''heure.</p><p><strong>B. Aqua Club :</strong> piscine olympique et bassin d''apprentissage. Ouvert de 10 h à 21 h. Aquagym pour les seniors tous les jours. Grand parking gratuit.</p><p><strong>C. Salle Énergie :</strong> musculation et cardio, ouvert 24 heures sur 24. Cours collectifs intensifs, plutôt pour les 18 à 35 ans. Pas de piscine. Parking gratuit.</p><p><strong>D. Centre Horizon :</strong> ouverture à 7 h du lundi au samedi. Programme Senior Actif : marche, étirements, équilibre. Bassin de 25 mètres. Parking gratuit pour les abonnés.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un abonnement (nom masculin) : vé tháng, gói hội viên\n• la gym douce (nom féminin) : thể dục nhẹ nhàng\n• un bassin (nom masculin) : bể bơi\n• les étirements (nom masculin pluriel) : bài giãn cơ\n• un abonné (nom masculin) : hội viên","explications":"• Đề thật cho 15 phút: mỗi tài liệu chỉ nên quét khoảng 2 phút.\n• Từ đồng nghĩa là bẫy quen thuộc: bassin là piscine, ouverture à 7 h là mở trước 9 h.","isPremium":true,"price":19000,"kyNang":"B1-CE-1","vong":"chot","thuTu":7}'::jsonb, '2026-11-04T00:00:03.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub012', 'b1ce04quj059', 1, 'tableau', 'Pour chaque document, cochez OUI ou NON.', '{"colonnes":[{"id":"cmw0y9qub00u","titre":"A"},{"id":"cmw0y9qub00v","titre":"B"},{"id":"cmw0y9qub00w","titre":"C"},{"id":"cmw0y9qub00x","titre":"D"}],"criteres":[{"id":"rmw0y9qub00y","texte":"Il y a des cours pour les seniors."},{"id":"rmw0y9qub00z","texte":"La salle ouvre avant 9 h."},{"id":"rmw0y9qub010","texte":"Il y a une piscine."},{"id":"rmw0y9qub011","texte":"Le parking est gratuit."}]}'::jsonb, '{"answers":{"rmw0y9qub00y_cmw0y9qub00u":"OUI","rmw0y9qub00y_cmw0y9qub00v":"OUI","rmw0y9qub00y_cmw0y9qub00w":"NON","rmw0y9qub00y_cmw0y9qub00x":"OUI","rmw0y9qub00z_cmw0y9qub00u":"OUI","rmw0y9qub00z_cmw0y9qub00v":"NON","rmw0y9qub00z_cmw0y9qub00w":"OUI","rmw0y9qub00z_cmw0y9qub00x":"OUI","rmw0y9qub010_cmw0y9qub00u":"OUI","rmw0y9qub010_cmw0y9qub00v":"OUI","rmw0y9qub010_cmw0y9qub00w":"NON","rmw0y9qub010_cmw0y9qub00x":"OUI","rmw0y9qub011_cmw0y9qub00u":"NON","rmw0y9qub011_cmw0y9qub00v":"OUI","rmw0y9qub011_cmw0y9qub00w":"OUI","rmw0y9qub011_cmw0y9qub00x":"OUI"}}'::jsonb, 'A: « parking payant ». B: « ouvert de 10 h à 21 h ». C: « plutôt pour les 18 à 35 ans », « pas de piscine ». D đạt cả bốn tiêu chí, « bassin de 25 mètres » cũng là hồ bơi.'), ('qmw0y9qub013', 'b1ce04quj059', 2, 'qcm', 'Quel abonnement offrez-vous à votre père ?', '{"options":["A. Forme Plus","B. Aqua Club","D. Centre Horizon"]}'::jsonb, '{"answer":2}'::jsonb, 'D: « ouverture à 7 h », « programme senior actif », « bassin de 25 mètres », « parking gratuit pour les abonnés ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce05quj05a', 'practice', 'Lecture B1 : les jeunes et l''information', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Les 15-25 ans s''informent autrement</strong></p><p>Selon une enquête publiée en septembre par l''institut Médiascope, huit jeunes sur dix découvrent l''actualité sur les réseaux sociaux. La télévision et la radio, qui restent les principales sources d''information de leurs parents, arrivent loin derrière : seuls 15 % des 15-25 ans regardent un journal télévisé chaque semaine.</p><p>Ce changement n''étonne pas les chercheurs. Pour Claire Fontaine, sociologue à l''université de Lille, les jeunes ne sont pas moins curieux qu''avant. Ils veulent simplement une information rapide, courte et disponible à tout moment sur leur téléphone. Une vidéo de deux minutes remplace souvent un long article.</p><p>Mais cette habitude a un prix. Sur les réseaux, les vraies nouvelles se mélangent aux rumeurs, et il est parfois difficile de savoir qui a écrit un message. D''après l''enquête, un jeune sur trois a déjà partagé une information avant de découvrir qu''elle était fausse.</p><p>Pour aider les élèves, de plus en plus de collèges et de lycées proposent des ateliers d''éducation aux médias. Les participants apprennent à vérifier une source, à comparer plusieurs articles et à reconnaître une photo truquée. Les premiers résultats sont encourageants : après six séances, les élèves repèrent deux fois plus de fausses informations.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une enquête (nom féminin) : cuộc khảo sát\n• l''actualité (nom féminin) : thời sự\n• une rumeur (nom féminin) : tin đồn\n• truqué (adjectif) : bị chỉnh sửa, giả\n• repérer (verbe) : nhận ra, phát hiện","explications":"• Ý chính của đoạn thường nằm ở câu đầu: « Mais cette habitude a un prix » báo trước một rủi ro.\n• Đáp án đúng hay đổi chữ: « vérifier une source » thành « vérifier d''où vient une information ».","kyNang":"B1-CE-2","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T00:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub014', 'b1ce05quj05a', 1, 'qcm', 'Cet article parle surtout…', '{"options":["de la fin de la télévision","de la façon dont les jeunes s''informent","du travail des journalistes"]}'::jsonb, '{"answer":1}'::jsonb, 'Tiêu đề « les 15-25 ans s''informent autrement » đã nói ý chính.'), ('qmw0y9qub015', 'b1ce05quj05a', 2, 'qcm', 'D''après l''enquête, la plupart des jeunes découvrent l''actualité…', '{"options":["à la télévision","sur les réseaux sociaux","dans les journaux"]}'::jsonb, '{"answer":1}'::jsonb, '« huit jeunes sur dix découvrent l''actualité sur les réseaux sociaux ».'), ('qmw0y9qub016', 'b1ce05quj05a', 3, 'qcm', 'Selon Claire Fontaine, les jeunes…', '{"options":["s''intéressent moins à l''actualité","veulent une information rapide et facile d''accès","préfèrent les longs articles"]}'::jsonb, '{"answer":1}'::jsonb, '« les jeunes ne sont pas moins curieux qu''avant », họ muốn « une information rapide, courte et disponible à tout moment ».'), ('qmw0y9qub017', 'b1ce05quj05a', 4, 'qcm', 'Le troisième paragraphe présente…', '{"options":["un risque de cette nouvelle habitude","l''avis des parents","une solution au problème"]}'::jsonb, '{"answer":0}'::jsonb, 'Câu chủ đề của đoạn: « mais cette habitude a un prix ».'), ('qmw0y9qub018', 'b1ce05quj05a', 5, 'qcm', 'Un jeune sur trois…', '{"options":["écrit des rumeurs","a déjà diffusé une fausse information sans le savoir","ne croit pas les réseaux sociaux"]}'::jsonb, '{"answer":1}'::jsonb, '« un jeune sur trois a déjà partagé une information avant de découvrir qu''elle était fausse ».'), ('qmw0y9qub019', 'b1ce05quj05a', 6, 'qcm', 'Dans les ateliers, les élèves apprennent surtout à…', '{"options":["vérifier d''où vient une information","écrire des articles de presse","créer des vidéos courtes"]}'::jsonb, '{"answer":0}'::jsonb, '« vérifier une source » là kiểm tra thông tin từ đâu ra.'), ('qmw0y9qub01a', 'b1ce05quj05a', 7, 'fill', 'Relevez dans le dernier paragraphe l''adjectif qui montre que les résultats des ateliers sont positifs.', '{}'::jsonb, '{"accepted":"encourageants"}'::jsonb, '« les premiers résultats sont encourageants ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce06quj05b', 'practice', 'Lecture B1 : une ville sans voitures', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Pontevedra, la ville où le piéton est roi</strong></p><p>Il y a vingt ans, le centre de Pontevedra, en Espagne, ressemblait à beaucoup d''autres villes : des rues pleines de voitures, du bruit et peu de place pour marcher. Aujourd''hui, des visiteurs viennent du monde entier pour voir comment cette ville de 80 000 habitants a presque fait disparaître les voitures de son centre.</p><p>Tout a commencé en 1999, quand le nouveau maire a décidé de fermer le centre historique à la circulation. Seuls les livreurs, les taxis et les véhicules des personnes handicapées peuvent encore y entrer, et leur vitesse est limitée à 30 km/h. Les parkings ont été construits à l''extérieur, à dix minutes à pied du centre.</p><p>Au début, beaucoup de commerçants étaient inquiets. Ils pensaient que leurs clients ne viendraient plus. C''est le contraire qui s''est passé : les rues piétonnes attirent davantage de promeneurs, et plusieurs boutiques ont ouvert dans des quartiers autrefois abandonnés.</p><p>Les effets sur la vie quotidienne sont nombreux. La pollution de l''air a fortement baissé, et les enfants vont de nouveau seuls à l''école. Le modèle a pourtant ses limites : les habitants des villages voisins, mal desservis par les bus, se plaignent de devoir faire un long trajet pour venir travailler en ville.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un piéton (nom masculin) : người đi bộ\n• la circulation (nom féminin) : giao thông\n• un commerçant (nom masculin) : người buôn bán\n• autrefois (adverbe) : trước kia\n• mal desservi (adjectif) : ít tuyến xe đi qua","explications":"• Đoạn cuối hay đổi hướng bằng « pourtant »: ý chính của đoạn nằm sau từ đó.\n• Câu hỏi về cả bài: đọc tiêu đề và câu cuối đoạn đầu.","isPremium":true,"price":19000,"kyNang":"B1-CE-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T00:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub01b', 'b1ce06quj05b', 1, 'qcm', 'Le thème principal de l''article est…', '{"options":["les problèmes de circulation en Espagne","la construction de nouveaux parkings","une ville qui a retiré les voitures de son centre"]}'::jsonb, '{"answer":2}'::jsonb, '« a presque fait disparaître les voitures de son centre ».'), ('qmw0y9qub01c', 'b1ce06quj05b', 2, 'qcm', 'Avant 1999, le centre de Pontevedra…', '{"options":["ressemblait à celui de beaucoup d''autres villes","était déjà réservé aux piétons","attirait des visiteurs du monde entier"]}'::jsonb, '{"answer":0}'::jsonb, '« ressemblait à beaucoup d''autres villes : des rues pleines de voitures ».'), ('qmw0y9qub01d', 'b1ce06quj05b', 3, 'qcm', 'Aujourd''hui, qui peut encore circuler dans le centre ?', '{"options":["tous les habitants du centre","quelques véhicules autorisés, comme les taxis","personne, sans exception"]}'::jsonb, '{"answer":1}'::jsonb, '« seuls les livreurs, les taxis et les véhicules des personnes handicapées peuvent encore y entrer ».'), ('qmw0y9qub01e', 'b1ce06quj05b', 4, 'qcm', 'Le troisième paragraphe montre que les commerçants…', '{"options":["ont fermé leurs boutiques","ont refusé le projet du maire","avaient peur pour rien"]}'::jsonb, '{"answer":2}'::jsonb, 'Họ lo khách không đến, nhưng « c''est le contraire qui s''est passé ».'), ('qmw0y9qub01f', 'b1ce06quj05b', 5, 'qcm', 'Quel effet positif l''article cite-t-il ?', '{"options":["Les bus sont plus nombreux.","L''air est moins pollué.","Les loyers ont baissé."]}'::jsonb, '{"answer":1}'::jsonb, '« la pollution de l''air a fortement baissé ».'), ('qmw0y9qub01g', 'b1ce06quj05b', 6, 'qcm', 'Le dernier paragraphe se termine sur…', '{"options":["l''avis des enfants","une limite du modèle","un nouveau projet du maire"]}'::jsonb, '{"answer":1}'::jsonb, '« le modèle a pourtant ses limites » rồi nói về người ở làng bên.'), ('qmw0y9qub01h', 'b1ce06quj05b', 7, 'fill', 'Relevez dans le deuxième paragraphe le nom qui désigne les personnes qui apportent des marchandises.', '{}'::jsonb, '{"accepted":"livreurs|les livreurs"}'::jsonb, '« seuls les livreurs, les taxis »: livreur là người giao hàng.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce07quk05c', 'practice', 'Lecture B1 : mieux dormir', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Dormir : pourquoi nous manquons de sommeil</strong></p><p>Les Français dorment en moyenne 6 heures 40 par nuit en semaine, soit presque une heure et demie de moins qu''il y a cinquante ans. Pour les médecins, ce chiffre est inquiétant : un adulte a besoin de sept à neuf heures de sommeil pour rester en bonne santé.</p><p>Les écrans sont souvent montrés du doigt. La lumière bleue des téléphones et des ordinateurs retarde l''endormissement, car elle fait croire au cerveau qu''il fait encore jour. Beaucoup de personnes consultent aussi leurs messages au lit, ce qui les empêche de se détendre.</p><p>Le rythme de vie joue également un rôle. Les longs trajets entre le domicile et le travail obligent certains salariés à se lever très tôt, tandis que les sorties et les séries regardées tard le soir repoussent l''heure du coucher.</p><p>Pourtant, quelques gestes simples suffisent souvent à mieux dormir. Les spécialistes conseillent de se coucher et de se lever à heures fixes, même le week-end, d''éviter le café après 16 heures et de laisser son téléphone hors de la chambre. Une courte sieste de vingt minutes en début d''après-midi peut aussi aider, à condition de ne pas la prolonger.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le sommeil (nom masculin) : giấc ngủ\n• montrer du doigt (expression) : chỉ trích, đổ lỗi\n• se détendre (verbe) : thư giãn\n• le coucher (nom masculin) : giờ đi ngủ\n• prolonger (verbe) : kéo dài","explications":"• Tóm mỗi đoạn bằng 3 đến 5 từ tiếng Việt ở lề nháp trước khi đọc câu hỏi.\n• Phương án chỉ lấy một chi tiết (« les séries ») thường không phải ý chính của đoạn.","isPremium":true,"price":19000,"kyNang":"B1-CE-2","vong":"hoc","thuTu":4}'::jsonb, '2026-11-04T00:00:06.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub01i', 'b1ce07quk05c', 1, 'qcm', 'Quelle phrase résume le premier paragraphe ?', '{"options":["Les Français dorment plus le week-end.","Nous dormons moins qu''avant, et ce n''est pas assez.","Les médecins dorment peu."]}'::jsonb, '{"answer":1}'::jsonb, '« presque une heure et demie de moins qu''il y a cinquante ans » và « un adulte a besoin de sept à neuf heures ».'), ('qmw0y9qub01j', 'b1ce07quk05c', 2, 'qcm', 'Quelle phrase résume le deuxième paragraphe ?', '{"options":["Il faut lire ses messages le soir.","Les écrans abîment les yeux.","Les écrans nous empêchent de nous endormir."]}'::jsonb, '{"answer":2}'::jsonb, '« la lumière bleue des téléphones et des ordinateurs retarde l''endormissement ».'), ('qmw0y9qub01k', 'b1ce07quk05c', 3, 'qcm', 'Pourquoi la lumière bleue gêne-t-elle le sommeil ?', '{"options":["Le cerveau pense qu''il fait encore jour.","Elle réveille les voisins.","Elle donne mal à la tête."]}'::jsonb, '{"answer":0}'::jsonb, '« elle fait croire au cerveau qu''il fait encore jour ».'), ('qmw0y9qub01l', 'b1ce07quk05c', 4, 'qcm', 'Quelle phrase résume le troisième paragraphe ?', '{"options":["Les séries sont trop longues.","Les salariés travaillent la nuit.","Notre manière de vivre réduit le temps de sommeil."]}'::jsonb, '{"answer":2}'::jsonb, 'Câu chủ đề: « le rythme de vie joue également un rôle ».'), ('qmw0y9qub01m', 'b1ce07quk05c', 5, 'qcm', 'Le quatrième paragraphe donne surtout…', '{"options":["des témoignages","des conseils","des chiffres"]}'::jsonb, '{"answer":1}'::jsonb, '« les spécialistes conseillent de se coucher et de se lever à heures fixes ».'), ('qmw0y9qub01n', 'b1ce07quk05c', 6, 'qcm', 'Que dit l''article sur la sieste ?', '{"options":["Elle est utile si elle reste courte.","Elle doit durer une heure.","Elle est déconseillée."]}'::jsonb, '{"answer":0}'::jsonb, '« une courte sieste de vingt minutes », « à condition de ne pas la prolonger ».'), ('qmw0y9qub01o', 'b1ce07quk05c', 7, 'fill', 'Relevez dans le deuxième paragraphe le nom qui signifie « le moment où l''on commence à dormir ».', '{}'::jsonb, '{"accepted":"endormissement|l''endormissement"}'::jsonb, '« retarde l''endormissement »: s''endormir là bắt đầu ngủ.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce08quk05d', 'practice', 'Lecture B1 : l''école autrement', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Une école sans notes ni sonnerie</strong></p><p><strong>1.</strong> Dans le petit village de Saint-Aubin, l''école Les Tilleuls ne ressemble à aucune autre. Ici, pas de sonnerie entre les cours, pas de notes sur 20 et pas de classes par âge : les 60 élèves, de 6 à 11 ans, travaillent ensemble dans de grandes salles ouvertes.</p><p><strong>2.</strong> Chaque lundi, chaque enfant choisit avec son enseignant les objectifs de sa semaine. Il organise ensuite lui-même son temps entre les mathématiques, la lecture et les projets. Les plus grands aident souvent les plus petits, ce qui leur permet de revoir ce qu''ils ont appris.</p><p><strong>3.</strong> L''après-midi, la classe sort régulièrement. Les élèves cultivent le jardin de l''école, observent les oiseaux de la rivière ou visitent les artisans du village. Pour la directrice, Hélène Morel, on apprend mieux ce qu''on a touché et vu de ses propres yeux.</p><p><strong>4.</strong> Ce fonctionnement ne plaît pas à tout le monde. Certains parents craignent que leurs enfants aient du mal à s''adapter au collège, où les règles sont plus strictes. Une mère a d''ailleurs retiré son fils l''an dernier, car il ne savait jamais s''il progressait.</p><p><strong>5.</strong> Les résultats semblent pourtant rassurer l''Éducation nationale. Aux évaluations nationales, les élèves des Tilleuls obtiennent des scores proches de la moyenne en français et un peu au-dessus en mathématiques. D''autres écoles de la région ont déjà demandé à visiter l''établissement.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une sonnerie (nom féminin) : chuông báo\n• un objectif (nom masculin) : mục tiêu\n• un artisan (nom masculin) : thợ thủ công\n• craindre (verbe) : sợ, lo\n• un établissement (nom masculin) : cơ sở, trường","explications":"• Ghép đoạn với tiêu đề: tìm câu chủ đề của mỗi đoạn, thường là câu đầu.\n• Luôn có một tiêu đề thừa: tiêu đề nói điều bài không hề nhắc.","isPremium":true,"price":19000,"kyNang":"B1-CE-2","vong":"on","thuTu":5}'::jsonb, '2026-11-04T00:00:07.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub020', 'b1ce08quk05d', 1, 'apparier', 'Associez chaque paragraphe à son titre. Un titre ne sert pas.', '{"items":[{"id":"imw0y9qub01p","texte":"Paragraphe 1"},{"id":"imw0y9qub01q","texte":"Paragraphe 2"},{"id":"imw0y9qub01r","texte":"Paragraphe 3"},{"id":"imw0y9qub01s","texte":"Paragraphe 4"},{"id":"imw0y9qub01t","texte":"Paragraphe 5"}],"choix":[{"id":"cmw0y9qub01u","texte":"Apprendre dehors"},{"id":"cmw0y9qub01v","texte":"Des inquiétudes chez les parents"},{"id":"cmw0y9qub01w","texte":"Une école différente"},{"id":"cmw0y9qub01x","texte":"Des résultats corrects"},{"id":"cmw0y9qub01y","texte":"Chacun organise son travail"},{"id":"cmw0y9qub01z","texte":"Une école qui va fermer"}]}'::jsonb, '{"answers":{"imw0y9qub01p":"cmw0y9qub01w","imw0y9qub01q":"cmw0y9qub01y","imw0y9qub01r":"cmw0y9qub01u","imw0y9qub01s":"cmw0y9qub01v","imw0y9qub01t":"cmw0y9qub01x"}}'::jsonb, '1: « ne ressemble à aucune autre ». 2: « il organise ensuite lui-même son temps ». 3: « la classe sort régulièrement ». 4: « certains parents craignent ». 5: « des scores proches de la moyenne ». Bài không nói trường sắp đóng cửa.'), ('qmw0y9qub021', 'b1ce08quk05d', 2, 'qcm', 'Dans cette école, les élèves…', '{"options":["ont des notes sur 20","changent de salle à chaque sonnerie","de plusieurs âges travaillent ensemble"]}'::jsonb, '{"answer":2}'::jsonb, '« pas de classes par âge », « travaillent ensemble dans de grandes salles ouvertes ».'), ('qmw0y9qub022', 'b1ce08quk05d', 3, 'qcm', 'Selon l''article, aider les plus petits permet aux grands de…', '{"options":["choisir leurs objectifs","gagner des points","revoir ce qu''ils savent"]}'::jsonb, '{"answer":2}'::jsonb, '« ce qui leur permet de revoir ce qu''ils ont appris ».'), ('qmw0y9qub023', 'b1ce08quk05d', 4, 'qcm', 'Selon la directrice, on apprend mieux…', '{"options":["dans le calme d''une classe","avec des livres","par l''expérience directe"]}'::jsonb, '{"answer":2}'::jsonb, '« on apprend mieux ce qu''on a touché et vu de ses propres yeux ».'), ('qmw0y9qub024', 'b1ce08quk05d', 5, 'qcm', 'Pourquoi une mère a-t-elle retiré son fils de l''école ?', '{"options":["Il s''ennuyait au jardin.","Il entrait au collège.","Il ne savait pas s''il faisait des progrès."]}'::jsonb, '{"answer":2}'::jsonb, '« il ne savait jamais s''il progressait ».'), ('qmw0y9qub025', 'b1ce08quk05d', 6, 'qcm', 'En mathématiques, les élèves des Tilleuls…', '{"options":["font un peu mieux que la moyenne","ont les meilleurs résultats du pays","sont très en retard"]}'::jsonb, '{"answer":0}'::jsonb, '« un peu au-dessus en mathématiques ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce09quk05e', 'practice', 'Lecture B1 : un article de presse', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Le grand retour des trains de nuit</strong></p><p>Longtemps considérés comme dépassés, les trains de nuit font leur retour en Europe. Depuis 2021, plusieurs lignes ont rouvert, comme Paris-Vienne ou Paris-Berlin, et d''autres sont prévues d''ici 2028. Leur promesse est simple : s''endormir dans une ville et se réveiller dans une autre, sans passer par l''aéroport.</p><p>Ce succès s''explique d''abord par l''inquiétude face au changement climatique. Un trajet en train émet jusqu''à vingt fois moins de CO2 qu''un vol équivalent. De plus en plus de voyageurs, surtout parmi les jeunes, acceptent de passer plus de temps dans les transports pour réduire leur impact sur la planète.</p><p>Le train de nuit présente aussi un avantage pratique : il fait gagner une nuit d''hôtel et arrive en plein centre-ville. Pour Marion, 34 ans, qui se rend à Vienne deux fois par an pour son travail, c''est devenu une évidence. Elle travaille dans le wagon-restaurant le soir, dort quelques heures et commence sa journée à 9 heures, reposée.</p><p>Tout n''est pourtant pas parfait. Les billets restent souvent plus chers que les vols à bas prix, les retards sont fréquents et le confort des couchettes est jugé insuffisant par de nombreux passagers. Les compagnies ferroviaires expliquent que les wagons sont anciens et que les nouveaux modèles ne seront pas livrés avant plusieurs années.</p><p>Les associations de voyageurs demandent donc aux États d''aider davantage ce mode de transport, par exemple en baissant les taxes sur les billets de train. Sans ce soutien, préviennent-elles, le retour des trains de nuit pourrait n''être qu''une mode passagère.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• dépassé (adjectif) : lỗi thời\n• émettre (verbe) : thải ra\n• une évidence (nom féminin) : điều hiển nhiên\n• une couchette (nom féminin) : giường nằm trên tàu\n• passager (adjectif) : thoáng qua, nhất thời","explications":"• Câu hỏi « ne… PAS »: gạch từng ý có trong bài, phương án còn lại là đáp án.\n• Bài báo B1 hay theo khuôn: hiện tượng, lý do, ví dụ, mặt trái, đề xuất.","isPremium":true,"price":19000,"kyNang":"B1-CE-2","vong":"chot","thuTu":6}'::jsonb, '2026-11-04T00:00:08.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub026', 'b1ce09quk05e', 1, 'qcm', 'L''article parle surtout…', '{"options":["de la fermeture de lignes de train","du retour d''un moyen de transport","des avantages de l''avion"]}'::jsonb, '{"answer":1}'::jsonb, '« les trains de nuit font leur retour en Europe ».'), ('qmw0y9qub027', 'b1ce09quk05e', 2, 'qcm', 'Selon le premier paragraphe, le train de nuit permet de…', '{"options":["visiter plusieurs villes en un jour","voyager en dormant","prendre l''avion plus facilement"]}'::jsonb, '{"answer":1}'::jsonb, '« s''endormir dans une ville et se réveiller dans une autre ».'), ('qmw0y9qub028', 'b1ce09quk05e', 3, 'qcm', 'Quelle est la première raison de ce succès ?', '{"options":["le prix des billets","la vitesse des trains","la préoccupation pour l''environnement"]}'::jsonb, '{"answer":2}'::jsonb, '« d''abord par l''inquiétude face au changement climatique ».'), ('qmw0y9qub029', 'b1ce09quk05e', 4, 'qcm', 'L''exemple de Marion montre que le train de nuit…', '{"options":["arrive trop tard pour travailler","peut être pratique pour les déplacements professionnels","est fatigant pour les salariés"]}'::jsonb, '{"answer":1}'::jsonb, '« qui se rend à Vienne deux fois par an pour son travail », « commence sa journée à 9 heures, reposée ».'), ('qmw0y9qub02a', 'b1ce09quk05e', 5, 'qcm', 'Quel problème l''article ne cite-t-il PAS ?', '{"options":["le prix élevé des billets","les retards fréquents","le manque de lignes vers l''Espagne"]}'::jsonb, '{"answer":2}'::jsonb, 'Đoạn 4 nêu « plus chers que les vols à bas prix », « les retards sont fréquents » và giường nằm. Không nhắc Tây Ban Nha.'), ('qmw0y9qub02b', 'b1ce09quk05e', 6, 'qcm', 'Pourquoi le confort ne s''améliore-t-il pas tout de suite ?', '{"options":["Les nouveaux wagons arriveront plus tard.","Les passagers ne se plaignent pas.","Les compagnies n''ont pas d''argent."]}'::jsonb, '{"answer":0}'::jsonb, '« les nouveaux modèles ne seront pas livrés avant plusieurs années ».'), ('qmw0y9qub02c', 'b1ce09quk05e', 7, 'qcm', 'Dans le dernier paragraphe, les associations…', '{"options":["demandent une aide publique","critiquent les voyageurs","veulent fermer certaines lignes"]}'::jsonb, '{"answer":0}'::jsonb, '« demandent donc aux États d''aider davantage ce mode de transport ».'), ('qmw0y9qub02d', 'b1ce09quk05e', 8, 'fill', 'Relevez dans le dernier paragraphe l''expression qui désigne une chose à la mode qui ne dure pas.', '{}'::jsonb, '{"accepted":"une mode passagère|mode passagère"}'::jsonb, '« pourrait n''être qu''une mode passagère ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce10quk05f', 'practice', 'Lecture B1 : vrai ou faux selon le texte ?', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Des abeilles sur les toits de Paris</strong></p><p>On les trouve sur le toit de l''Opéra, de grands hôtels ou de simples immeubles : Paris compte aujourd''hui environ 700 ruches. Ce chiffre a été multiplié par trois en dix ans.</p><p>Contrairement à ce que l''on pourrait croire, les abeilles se portent plutôt bien en ville. Les parcs, les jardins et les arbres des avenues leur offrent des fleurs très variées, et on y utilise beaucoup moins de pesticides que dans les champs. Résultat : une ruche parisienne produit en moyenne plus de miel qu''une ruche de campagne.</p><p>Les apiculteurs urbains restent cependant prudents. Selon eux, il y a désormais trop de ruches dans certains quartiers, et les abeilles manquent de fleurs au printemps. La mairie conseille donc aux habitants de planter des fleurs sur leurs balcons plutôt que d''installer de nouvelles ruches.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une ruche (nom féminin) : tổ ong nuôi\n• une abeille (nom féminin) : con ong\n• se porter bien (expression) : khoẻ mạnh\n• un apiculteur (nom masculin) : người nuôi ong\n• désormais (adverbe) : từ nay, giờ đây","explications":"• Chọn theo bài, không theo điều mình biết: bài này cố ý nói ngược với suy nghĩ thông thường.\n• Tìm đúng câu trong bài tương ứng với khẳng định, rồi mới chọn Vrai hay Faux.","kyNang":"B1-CE-3","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T00:00:09.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub02e', 'b1ce10quk05f', 1, 'qcm', 'Le nombre de ruches à Paris a augmenté ces dernières années.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« ce chiffre a été multiplié par trois en dix ans ».'), ('qmw0y9qub02f', 'b1ce10quk05f', 2, 'qcm', 'Les abeilles vivent mal en ville.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, 'Nhiều người nghĩ vậy, nhưng bài nói ngược lại: « les abeilles se portent plutôt bien en ville ».'), ('qmw0y9qub02g', 'b1ce10quk05f', 3, 'qcm', 'En ville, on utilise moins de pesticides que dans les champs.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« on y utilise beaucoup moins de pesticides que dans les champs ».'), ('qmw0y9qub02h', 'b1ce10quk05f', 4, 'qcm', 'Une ruche de campagne produit plus de miel qu''une ruche parisienne.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« une ruche parisienne produit en moyenne plus de miel qu''une ruche de campagne ».'), ('qmw0y9qub02i', 'b1ce10quk05f', 5, 'qcm', 'Selon les apiculteurs, on peut encore installer beaucoup de ruches dans tous les quartiers.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« il y a désormais trop de ruches dans certains quartiers ».'), ('qmw0y9qub02j', 'b1ce10quk05f', 6, 'qcm', 'La mairie encourage les habitants à planter des fleurs.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« la mairie conseille donc aux habitants de planter des fleurs sur leurs balcons ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce11quk05g', 'practice', 'Lecture B1 : le vélo au travail', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Au travail à vélo : l''entreprise paie</strong></p><p>Depuis janvier, la société lyonnaise Datavia verse 50 euros par mois aux salariés qui viennent travailler à vélo. Sur ses 120 employés, 38 ont déjà profité de cette aide, contre une dizaine de cyclistes seulement l''année dernière.</p><p>Pour recevoir la prime, il suffit de déclarer ses trajets sur une application. L''entreprise a aussi installé un garage à vélos sécurisé et deux douches, une demande ancienne des salariés qui habitent loin.</p><p>Le directeur, Thomas Ricard, ne cache pas que la mesure coûte cher. Mais il constate déjà moins d''arrêts maladie et une meilleure ambiance dans les équipes. Seul regret : les employés qui vivent à plus de 20 kilomètres continuent presque tous à prendre la voiture.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• verser (verbe) : trả, chuyển (tiền)\n• une prime (nom féminin) : tiền thưởng, trợ cấp\n• déclarer (verbe) : khai báo\n• un arrêt maladie (nom masculin) : nghỉ ốm\n• un regret (nom masculin) : điều tiếc","explications":"• Để ý từ chỉ thời gian và số lượng: « depuis janvier », « presque tous ».\n• « Il suffit de » nghĩa là chỉ cần, không có thủ tục nào khác.","isPremium":true,"price":19000,"kyNang":"B1-CE-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T00:00:10.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub02k', 'b1ce11quk05g', 1, 'qcm', 'Datavia aide les cyclistes depuis plusieurs années.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« depuis janvier »: mới từ đầu năm nay.'), ('qmw0y9qub02l', 'b1ce11quk05g', 2, 'qcm', 'Plus de salariés viennent à vélo qu''avant.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« 38 ont déjà profité de cette aide, contre une dizaine de cyclistes seulement l''année dernière ».'), ('qmw0y9qub02m', 'b1ce11quk05g', 3, 'qcm', 'Pour avoir la prime, il faut présenter un justificatif au directeur chaque semaine.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« il suffit de déclarer ses trajets sur une application ».'), ('qmw0y9qub02n', 'b1ce11quk05g', 4, 'qcm', 'Les salariés avaient demandé des douches depuis longtemps.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« une demande ancienne des salariés qui habitent loin ».'), ('qmw0y9qub02o', 'b1ce11quk05g', 5, 'qcm', 'Selon le directeur, la mesure ne coûte presque rien.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« ne cache pas que la mesure coûte cher ».'), ('qmw0y9qub02p', 'b1ce11quk05g', 6, 'qcm', 'La plupart des employés qui habitent loin utilisent encore leur voiture.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« continuent presque tous à prendre la voiture ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce12quk05h', 'practice', 'Lecture B1 : vivre sans téléphone', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Une semaine sans smartphone</strong></p><p>En mars, 200 lycéens de Rennes ont accepté de laisser leur smartphone dans une boîte pendant une semaine. L''idée venait d''une professeure de philosophie, Anne Kerlo, qui voulait faire réfléchir ses élèves à leur relation avec les écrans.</p><p>Les deux premiers jours ont été les plus durs. Beaucoup d''élèves disent avoir ressenti de l''angoisse, surtout le soir, par peur de manquer une conversation entre amis. Certains ont dû acheter un vieux réveil, car ils utilisaient leur téléphone pour se lever le matin.</p><p>Ensuite, les choses ont changé. Les participants ont redécouvert les jeux de société, les discussions pendant les repas et même la lecture. Une majorité affirme avoir mieux dormi. Pourtant, à la fin de l''expérience, presque tous ont repris leur téléphone avec plaisir : seuls quelques-uns ont décidé de limiter son usage à une heure par jour.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un lycéen (nom masculin) : học sinh cấp ba\n• l''angoisse (nom féminin) : nỗi lo âu\n• un réveil (nom masculin) : đồng hồ báo thức\n• redécouvrir (verbe) : khám phá lại\n• l''usage (nom masculin) : việc sử dụng","explications":"• « Une majorité » là đa số, « quelques-uns » là vài người: đừng nhầm hai lượng này.\n• Câu có « surtout » hỏi lý do chính: đối chiếu đúng lý do bài nêu.","isPremium":true,"price":19000,"kyNang":"B1-CE-3","vong":"on","thuTu":4}'::jsonb, '2026-11-04T00:00:11.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub02q', 'b1ce12quk05h', 1, 'qcm', 'L''expérience a été proposée par les élèves eux-mêmes.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« l''idée venait d''une professeure de philosophie ».'), ('qmw0y9qub02r', 'b1ce12quk05h', 2, 'qcm', 'Le début de la semaine a été difficile.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« les deux premiers jours ont été les plus durs ».'), ('qmw0y9qub02s', 'b1ce12quk05h', 3, 'qcm', 'Les élèves avaient surtout peur de ne pas pouvoir faire leurs devoirs.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« par peur de manquer une conversation entre amis ».'), ('qmw0y9qub02t', 'b1ce12quk05h', 4, 'qcm', 'Certains élèves ont eu besoin d''un autre objet pour se réveiller.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« certains ont dû acheter un vieux réveil ».'), ('qmw0y9qub02u', 'b1ce12quk05h', 5, 'qcm', 'La plupart des participants disent avoir mieux dormi.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« une majorité affirme avoir mieux dormi ».'), ('qmw0y9qub02v', 'b1ce12quk05h', 6, 'qcm', 'Après l''expérience, la majorité a décidé d''utiliser son téléphone une heure par jour.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« seuls quelques-uns ont décidé de limiter son usage à une heure par jour ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce13qum05i', 'practice', 'Lecture B1 : vrai ou faux dans l''article', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Les ressourceries, magasins de seconde vie</strong></p><p>Dans une ancienne usine de Nantes, on trouve des chaises, des vélos, des livres et même des pianos. Tous ces objets ont été donnés par des habitants et réparés par l''équipe de la ressourcerie La Fabrique, ouverte en 2019. Chaque année, l''association récupère près de 300 tonnes d''objets qui auraient sinon fini à la poubelle.</p><p>Le principe est simple. Les habitants déposent gratuitement ce dont ils n''ont plus besoin. Les objets sont triés, nettoyés, parfois transformés, puis revendus à petit prix dans le magasin. Une commode coûte par exemple 40 euros, environ cinq fois moins cher que neuve.</p><p>La ressourcerie a aussi un rôle social. Elle emploie 25 salariés, dont la moitié étaient au chômage depuis longtemps. Pendant deux ans, ils apprennent un métier, comme la menuiserie ou la réparation électrique, avant de chercher un emploi ailleurs. Selon le directeur, Karim Haddad, sept sur dix trouvent ensuite un travail.</p><p>Le succès est tel que le magasin manque désormais de place. L''association cherche un nouveau local, plus grand, mais les loyers sont élevés dans le centre-ville. Elle a lancé un appel aux dons pour pouvoir déménager avant la fin de l''année prochaine.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une ressourcerie (nom féminin) : cửa hàng đồ cũ tái sử dụng\n• trier (verbe) : phân loại\n• une commode (nom féminin) : tủ ngăn kéo\n• le chômage (nom masculin) : thất nghiệp\n• un local (nom masculin) : mặt bằng, cơ sở","explications":"• Đề thật trộn Vrai/Faux với A/B/C: đọc câu hỏi theo thứ tự, vì chúng đi theo thứ tự bài.\n• Bài viết năm 2026: « ouverte en 2019 » là khoảng bảy năm.","isPremium":true,"price":19000,"kyNang":"B1-CE-3","vong":"chot","thuTu":5}'::jsonb, '2026-11-04T00:00:12.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub02w', 'b1ce13qum05i', 1, 'qcm', 'La Fabrique existe depuis plus de dix ans.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« ouverte en 2019 ».'), ('qmw0y9qub02x', 'b1ce13qum05i', 2, 'qcm', 'Les habitants doivent payer pour déposer leurs objets.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« les habitants déposent gratuitement ».'), ('qmw0y9qub02y', 'b1ce13qum05i', 3, 'qcm', 'Une commode d''occasion coûte…', '{"options":["beaucoup moins cher qu''une commode neuve","le même prix qu''une commode neuve","deux fois plus cher qu''en magasin"]}'::jsonb, '{"answer":0}'::jsonb, '« environ cinq fois moins cher que neuve ».'), ('qmw0y9qub02z', 'b1ce13qum05i', 4, 'qcm', 'Une partie des salariés n''avait pas de travail avant.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« dont la moitié étaient au chômage depuis longtemps ».'), ('qmw0y9qub030', 'b1ce13qum05i', 5, 'qcm', 'Les salariés restent à la ressourcerie…', '{"options":["toute leur carrière","pendant deux ans","quelques semaines"]}'::jsonb, '{"answer":1}'::jsonb, '« pendant deux ans, ils apprennent un métier ».'), ('qmw0y9qub031', 'b1ce13qum05i', 6, 'qcm', 'La majorité des salariés trouve un emploi après la ressourcerie.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":0}'::jsonb, '« sept sur dix trouvent ensuite un travail ».'), ('qmw0y9qub032', 'b1ce13qum05i', 7, 'qcm', 'Aujourd''hui, le principal problème de l''association est…', '{"options":["le manque d''espace","le manque de clients","le manque d''objets"]}'::jsonb, '{"answer":0}'::jsonb, '« le magasin manque désormais de place ».'), ('qmw0y9qub033', 'b1ce13qum05i', 8, 'qcm', 'L''association a déjà trouvé un nouveau local.', '{"options":["Vrai","Faux"]}'::jsonb, '{"answer":1}'::jsonb, '« l''association cherche un nouveau local »: vẫn đang tìm.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce14qum05j', 'practice', 'Lecture B1 : devinez le sens', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions.</p>', '<p><strong>Le dimanche aux puces</strong></p><p>Chaque dimanche, Lucie se lève à l''aube, bien avant le lever du soleil, pour aller aux puces de Saint-Ouen. Elle aime y chiner : passer des heures entre les stands à la recherche d''un objet ancien que personne n''a encore remarqué.</p><p>Ce matin, elle flâne sans se presser dans les allées. Elle ne cherche rien de précis. Soudain, au fond d''un stand rempli de bibelots, ces petits objets décoratifs que l''on pose sur une étagère, elle déniche une vieille lampe en cuivre. Elle n''en revient pas : c''est exactement le modèle qu''elle cherchait depuis des années.</p><p>Le vendeur en demande 80 euros. Lucie trouve que c''est trop. Elle marchande pendant dix minutes, propose 50, puis 55 euros. Finalement, le vendeur accepte 60 euros. Pour une lampe de cette qualité, c''est une véritable aubaine : dans une boutique d''antiquités, elle coûterait trois fois plus.</p><p>Sur le chemin du retour, Lucie est ravie, mais un peu inquiète : son appartement est déjà encombré, et elle ne sait pas encore où elle va mettre sa nouvelle trouvaille.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• les puces (nom féminin pluriel) : chợ đồ cũ\n• une allée (nom féminin) : lối đi\n• le cuivre (nom masculin) : đồng (kim loại)\n• encombré (adjectif) : chật, bừa đồ\n• une trouvaille (nom féminin) : món tìm được","explications":"• Từ lạ thường được giải thích ngay sau dấu phẩy hoặc dấu hai chấm.\n• Không biết từ: đọc câu trước và câu sau, đoán nghĩa tích cực hay tiêu cực trước.","kyNang":"B1-CE-4","vong":"hoc","thuTu":1}'::jsonb, '2026-11-04T00:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub034', 'b1ce14qum05j', 1, 'qcm', 'Dans le texte, « à l''aube » signifie…', '{"options":["le soir","en retard","très tôt le matin"]}'::jsonb, '{"answer":2}'::jsonb, 'Câu tự giải thích ngay sau: « bien avant le lever du soleil ».'), ('qmw0y9qub035', 'b1ce14qum05j', 2, 'qcm', '« Chiner » signifie…', '{"options":["chercher des objets anciens","nettoyer un stand","vendre des meubles"]}'::jsonb, '{"answer":0}'::jsonb, 'Dấu hai chấm giải thích từ: « à la recherche d''un objet ancien ».'), ('qmw0y9qub036', 'b1ce14qum05j', 3, 'qcm', '« Flâner » signifie…', '{"options":["se promener lentement","courir","se perdre"]}'::jsonb, '{"answer":0}'::jsonb, '« sans se presser » và « elle ne cherche rien de précis ».'), ('qmw0y9qub037', 'b1ce14qum05j', 4, 'qcm', '« Dénicher » signifie…', '{"options":["acheter cher","trouver une chose rare","casser"]}'::jsonb, '{"answer":1}'::jsonb, 'Câu sau: « c''est exactement le modèle qu''elle cherchait depuis des années ».'), ('qmw0y9qub038', 'b1ce14qum05j', 5, 'qcm', '« Elle n''en revient pas » veut dire qu''elle est…', '{"options":["fatiguée","déçue","très surprise"]}'::jsonb, '{"answer":2}'::jsonb, 'Cô vừa tìm được đúng mẫu đèn « qu''elle cherchait depuis des années »: ngạc nhiên vì may.'), ('qmw0y9qub039', 'b1ce14qum05j', 6, 'qcm', '« Marchander » signifie…', '{"options":["refuser d''acheter","payer en espèces","discuter pour payer moins"]}'::jsonb, '{"answer":2}'::jsonb, '« propose 50, puis 55 euros » trong khi người bán đòi 80.'), ('qmw0y9qub03a', 'b1ce14qum05j', 7, 'fill', 'Relevez dans le texte le mot qui désigne de petits objets décoratifs.', '{}'::jsonb, '{"accepted":"bibelots|des bibelots"}'::jsonb, '« ces petits objets décoratifs que l''on pose sur une étagère » giải thích từ đứng trước nó.'), ('qmw0y9qub03b', 'b1ce14qum05j', 8, 'fill', 'Relevez le mot qui signifie « une très bonne affaire ».', '{}'::jsonb, '{"accepted":"aubaine|une aubaine|une véritable aubaine"}'::jsonb, 'Ngay sau là lý do: « elle coûterait trois fois plus ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce15qum05k', 'practice', 'Lecture B1 : la famille des mots', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions.</p>', '<p><strong>Un premier mois en colocation</strong></p><p>Quand Inès a emménagé avec trois colocataires, elle s''attendait à quelques désaccords. Elle n''imaginait pas que le premier mois serait aussi inoubliable.</p><p>Dès le premier jour, le déménagement a mal commencé : le camion est arrivé avec deux heures de retard, et le chauffeur, un peu malhonnête, a demandé trente euros de plus. Une fois installés, les colocataires ont découvert que l''appartement manquait de rangements : impossible de trouver une place pour les livres d''Inès.</p><p>Ils ont donc décidé de réorganiser le salon. Ensemble, ils ont repeint les murs, monté des étagères et écrit les règles de la maison sur un grand tableau. Malheureusement, l''écriture de Paul était presque illisible, et il a fallu tout recopier.</p><p>Aujourd''hui, Inès en rit. Vivre seule lui paraît désormais impensable : selon elle, la colocation lui a appris la patience et le partage.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• emménager (verbe) : dọn đến ở\n• un colocataire (nom masculin) : bạn ở chung nhà\n• un désaccord (nom masculin) : sự bất đồng\n• une étagère (nom féminin) : kệ\n• le partage (nom masculin) : sự chia sẻ","explications":"• Tiền tố in-, im-, il-, dés-, mal- thường mang nghĩa phủ định; re-, ré- là làm lại.\n• Hậu tố -able, -ible là có thể; -ment biến động từ thành danh từ.","kyNang":"B1-CE-4","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T00:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub03c', 'b1ce15qum05k', 1, 'qcm', 'Dans le mot « désaccords », le début dés- indique…', '{"options":["le contraire","la répétition","un lieu"]}'::jsonb, '{"answer":0}'::jsonb, 'dés + accord: không đồng ý, tức là bất đồng.'), ('qmw0y9qub03d', 'b1ce15qum05k', 2, 'qcm', 'Un mois « inoubliable » est un mois…', '{"options":["qu''on a déjà oublié","qu''on ne peut pas oublier","qu''on veut oublier"]}'::jsonb, '{"answer":1}'::jsonb, 'in- là không, -able là có thể: không thể quên.'), ('qmw0y9qub03e', 'b1ce15qum05k', 3, 'qcm', 'Un chauffeur « malhonnête » est un chauffeur…', '{"options":["très poli","malade","qui n''est pas honnête"]}'::jsonb, '{"answer":2}'::jsonb, 'mal + honnête: không trung thực. Ông đòi thêm tiền: « a demandé trente euros de plus ».'), ('qmw0y9qub03f', 'b1ce15qum05k', 4, 'qcm', 'Des « rangements » sont…', '{"options":["les règles de la maison","des endroits pour ranger ses affaires","des personnes qui rangent"]}'::jsonb, '{"answer":1}'::jsonb, 'ranger + -ment tạo danh từ. Câu sau: « impossible de trouver une place pour les livres ».'), ('qmw0y9qub03g', 'b1ce15qum05k', 5, 'qcm', 'Dans « réorganiser » et « recopier », le début re- ou ré- signifie…', '{"options":["de nouveau","pas","avant"]}'::jsonb, '{"answer":0}'::jsonb, '« réorganiser le salon » là sắp xếp lại, « tout recopier » là chép lại.'), ('qmw0y9qub03h', 'b1ce15qum05k', 6, 'qcm', 'Une écriture « illisible » est une écriture…', '{"options":["écrite à l''ordinateur","qu''on ne peut pas lire","très belle"]}'::jsonb, '{"answer":1}'::jsonb, 'il- là không, -ible là có thể. Vì thế « il a fallu tout recopier ».'), ('qmw0y9qub03i', 'b1ce15qum05k', 7, 'fill', 'Trouvez dans le texte le nom formé sur le verbe « déménager ».', '{}'::jsonb, '{"accepted":"déménagement|le déménagement"}'::jsonb, '« le déménagement a mal commencé »: déménager + -ment.'), ('qmw0y9qub03j', 'b1ce15qum05k', 8, 'fill', 'Trouvez dans le texte l''adjectif qui signifie « qu''on ne peut pas imaginer ».', '{}'::jsonb, '{"accepted":"impensable"}'::jsonb, '« vivre seule lui paraît désormais impensable »: im- + penser + -able.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce16qun05l', 'practice', 'Lecture B1 : ce que l''auteur veut dire', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions.</p>', '<p><strong>Le jour où j''ai vendu ma voiture</strong></p><p>Il y a deux ans, j''ai vendu ma voiture. Mes amis m''ont regardé comme si j''avais perdu la tête : comment allais-je faire les courses, partir en vacances, rendre visite à ma mère qui vit à la campagne ?</p><p>Les premières semaines, je dois l''avouer, j''ai souvent regretté ma décision. Le bus de 7 h 12 passait rarement à 7 h 12, et la pluie de novembre ne m''a pas épargné. Puis, peu à peu, j''ai pris d''autres habitudes. Je fais mes courses au marché du quartier, à pied, et je connais maintenant le prénom de tous les commerçants.</p><p>Pour aller voir ma mère, je prends le train du samedi. Elle vient me chercher à la gare, et nous avons ainsi vingt minutes de conversation en plus, que nous n''avions jamais quand je conduisais en écoutant la radio.</p><p>Je ne dirai pas que tout le monde devrait m''imiter. Quand on habite loin de tout, la voiture reste indispensable. Mais pour moi, et pour mon compte en banque, ce fut sans doute la meilleure décision de la décennie.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• avouer (verbe) : thú nhận\n• épargner (verbe) : tha, chừa ra\n• imiter (verbe) : bắt chước\n• indispensable (adjectif) : không thể thiếu\n• une décennie (nom féminin) : thập kỷ","explications":"• Câu hỏi suy luận không lặp chữ của bài: tìm câu có cùng ý rồi diễn đạt lại.\n• Đáp án quá mạnh (« tout le monde devrait ») thường sai khi tác giả nói có chừng mực.","isPremium":true,"price":19000,"kyNang":"B1-CE-4","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T00:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub03k', 'b1ce16qun05l', 1, 'qcm', 'Au début, les amis de l''auteur…', '{"options":["l''ont aidé à vendre sa voiture","trouvaient son choix déraisonnable","ont fait comme lui"]}'::jsonb, '{"answer":1}'::jsonb, '« comme si j''avais perdu la tête »: như thể anh ấy mất trí.'), ('qmw0y9qub03l', 'b1ce16qun05l', 2, 'qcm', 'Que comprend-on à propos du bus de 7 h 12 ?', '{"options":["Il était souvent en retard.","Il était toujours plein.","Il ne roulait pas en novembre."]}'::jsonb, '{"answer":0}'::jsonb, '« passait rarement à 7 h 12 »: hiếm khi đúng giờ.'), ('qmw0y9qub03m', 'b1ce16qun05l', 3, 'qcm', '« La pluie de novembre ne m''a pas épargné » signifie que l''auteur…', '{"options":["aime la pluie","a souvent été mouillé","est resté chez lui"]}'::jsonb, '{"answer":1}'::jsonb, 'Đi bộ, chờ xe buýt dưới mưa: mưa không tha anh ấy.'), ('qmw0y9qub03n', 'b1ce16qun05l', 4, 'qcm', 'Aujourd''hui, au marché, l''auteur…', '{"options":["y va en bus","achète moins qu''avant","a créé des liens avec les vendeurs"]}'::jsonb, '{"answer":2}'::jsonb, '« je connais maintenant le prénom de tous les commerçants ».'), ('qmw0y9qub03o', 'b1ce16qun05l', 5, 'qcm', 'Qu''est-ce qui a changé dans ses visites à sa mère ?', '{"options":["Il la voit moins souvent.","Ils parlent davantage ensemble.","Elle vient chez lui en voiture."]}'::jsonb, '{"answer":1}'::jsonb, '« vingt minutes de conversation en plus ».'), ('qmw0y9qub03p', 'b1ce16qun05l', 6, 'qcm', 'Quelle est l''opinion finale de l''auteur ?', '{"options":["Sa solution lui convient, mais pas à tout le monde.","Il regrette d''avoir vendu sa voiture.","Tout le monde devrait vendre sa voiture."]}'::jsonb, '{"answer":0}'::jsonb, '« je ne dirai pas que tout le monde devrait m''imiter » nhưng với anh là « la meilleure décision de la décennie ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce17qun05m', 'practice', 'Lecture B1 : un texte difficile', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions.</p>', '<p><strong>Les glaneurs reviennent dans les champs</strong></p><p>Dans les champs de la Beauce, une fois la récolte terminée, on voit parfois des silhouettes courbées ramasser les pommes de terre oubliées par les machines. Ce sont des glaneurs. Le glanage, cette pratique très ancienne qui consiste à récupérer ce qui reste après la moisson, est toujours autorisé par la loi, à condition de le faire de jour et après le passage de l''agriculteur.</p><p>Longtemps réservé aux plus pauvres, il attire aujourd''hui un public plus varié : des retraités, des étudiants, des familles soucieuses de lutter contre le gaspillage. Car les chiffres font frémir : chaque année, des milliers de tonnes de légumes parfaitement comestibles restent dans les champs, simplement parce qu''ils sont trop petits ou un peu abîmés pour être vendus.</p><p>Certains agriculteurs voient d''un bon œil ces visiteurs, qui nettoient leurs terres gratuitement. D''autres se méfient : ils craignent les vols et les dégâts dans les cultures voisines. Pour apaiser les tensions, des associations organisent désormais des sorties encadrées, avec l''accord des propriétaires.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la récolte (nom féminin) : vụ thu hoạch\n• courbé (adjectif) : cúi lom khom\n• le gaspillage (nom masculin) : sự lãng phí\n• abîmé (adjectif) : bị dập, hư một phần\n• se méfier (verbe) : nghi ngại, đề phòng","explications":"• Bài nhiều từ mới: đọc hết đoạn một lượt, đừng dừng ở từ đầu tiên không biết.\n• Thành ngữ (« voir d''un bon œil ») đoán qua câu đối lập đứng gần.","isPremium":true,"price":19000,"kyNang":"B1-CE-4","vong":"on","thuTu":4}'::jsonb, '2026-11-04T00:00:16.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub03q', 'b1ce17qun05m', 1, 'qcm', 'Les « glaneurs » sont des personnes qui…', '{"options":["ramassent ce qui reste dans les champs","conduisent les machines agricoles","vendent des légumes au marché"]}'::jsonb, '{"answer":0}'::jsonb, '« ramasser les pommes de terre oubliées par les machines ».'), ('qmw0y9qub03r', 'b1ce17qun05m', 2, 'qcm', '« Les chiffres font frémir » signifie que les chiffres sont…', '{"options":["inquiétants","faux","difficiles à calculer"]}'::jsonb, '{"answer":0}'::jsonb, 'Ngay sau là con số lãng phí: « des milliers de tonnes de légumes ».'), ('qmw0y9qub03s', 'b1ce17qun05m', 3, 'qcm', 'Des légumes « comestibles » sont des légumes…', '{"options":["qu''on peut manger","très chers","déjà cuisinés"]}'::jsonb, '{"answer":0}'::jsonb, 'Rau bị bỏ chỉ vì « trop petits ou un peu abîmés », tức là vẫn ăn được.'), ('qmw0y9qub03t', 'b1ce17qun05m', 4, 'qcm', '« Voient d''un bon œil » signifie que ces agriculteurs…', '{"options":["surveillent les glaneurs","acceptent volontiers les glaneurs","ne remarquent pas les glaneurs"]}'::jsonb, '{"answer":1}'::jsonb, 'Lý do tích cực « qui nettoient leurs terres gratuitement », đối lập với « d''autres se méfient ».'), ('qmw0y9qub03u', 'b1ce17qun05m', 5, 'fill', 'Relevez dans le premier paragraphe le nom qui désigne la pratique de ramasser ce qui reste après la récolte.', '{}'::jsonb, '{"accepted":"glanage|le glanage"}'::jsonb, '« le glanage, cette pratique très ancienne qui consiste à récupérer ce qui reste ».'), ('qmw0y9qub03v', 'b1ce17qun05m', 6, 'fill', 'Relevez dans le dernier paragraphe le verbe qui signifie « calmer ».', '{}'::jsonb, '{"accepted":"apaiser"}'::jsonb, '« pour apaiser les tensions »: làm dịu căng thẳng.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce18qun05n', 'practice', 'Lecture B1 : six questions difficiles', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions.</p>', '<p><strong>Lussac, village des télétravailleurs</strong></p><p>Depuis trois ans, le village de Lussac, 600 habitants, a vu arriver une quarantaine de nouveaux venus. Ils ne sont ni agriculteurs ni retraités : ce sont des graphistes, des comptables ou des développeurs qui travaillent à distance pour des entreprises parisiennes. Le maire, qui craignait de voir fermer l''école faute d''élèves, se frotte les mains : une classe supplémentaire a même ouvert à la rentrée.</p><p>L''intégration ne se fait pourtant pas sans heurts. Certains anciens habitants reprochent aux nouveaux de faire grimper le prix des maisons et de rester enfermés devant leur écran. Les nouveaux, eux, découvrent que la vie à la campagne a ses contraintes : la connexion internet est capricieuse, et la boulangerie la plus proche est à huit kilomètres.</p><p>Pour rapprocher les deux groupes, la mairie a transformé l''ancienne poste en espace de travail partagé, où l''on peut aussi boire un café et lire le journal. Le pari semble réussi : le vendredi soir, on y croise désormais autant de chasseurs que de développeurs.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• à distance (expression) : từ xa\n• faute de (préposition) : vì thiếu\n• reprocher (verbe) : trách\n• grimper (verbe) : leo, tăng vọt\n• un pari (nom masculin) : canh bạc, việc đặt cược","explications":"• Thành ngữ chỉ cảm xúc (« se frotter les mains ») đoán qua sự việc kể ngay sau.\n• Từ « pourtant » ở đầu đoạn báo trước chuyện không suôn sẻ.","isPremium":true,"price":19000,"kyNang":"B1-CE-4","vong":"chot","thuTu":5}'::jsonb, '2026-11-04T00:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub03w', 'b1ce18qun05n', 1, 'qcm', '« Le maire se frotte les mains » signifie qu''il est…', '{"options":["satisfait","inquiet","en colère"]}'::jsonb, '{"answer":0}'::jsonb, 'Lý do ngay sau: « une classe supplémentaire a même ouvert à la rentrée ».'), ('qmw0y9qub03x', 'b1ce18qun05n', 2, 'qcm', 'Pourquoi le maire était-il inquiet avant ?', '{"options":["Il risquait de ne plus y avoir assez d''enfants.","La poste allait fermer.","Les agriculteurs quittaient le village."]}'::jsonb, '{"answer":0}'::jsonb, '« craignait de voir fermer l''école faute d''élèves »: faute de là vì thiếu.'), ('qmw0y9qub03y', 'b1ce18qun05n', 3, 'qcm', '« Sans heurts » signifie…', '{"options":["sans retard","sans argent","sans difficultés ni conflits"]}'::jsonb, '{"answer":2}'::jsonb, '« pourtant pas sans heurts » rồi kể chuyện trách móc: « certains anciens habitants reprochent ».'), ('qmw0y9qub03z', 'b1ce18qun05n', 4, 'qcm', 'Une connexion « capricieuse » est une connexion…', '{"options":["très rapide","trop chère","qui ne marche pas toujours bien"]}'::jsonb, '{"answer":2}'::jsonb, 'Nằm trong danh sách « ses contraintes », cạnh tiệm bánh ở xa tám cây số.'), ('qmw0y9qub040', 'b1ce18qun05n', 5, 'qcm', 'Que reprochent certains anciens habitants aux nouveaux ?', '{"options":["Ils ne paient pas leurs impôts.","Ils font monter les prix et restent entre eux.","Ils font trop de bruit le soir."]}'::jsonb, '{"answer":1}'::jsonb, '« faire grimper le prix des maisons » và « rester enfermés devant leur écran ».'), ('qmw0y9qub041', 'b1ce18qun05n', 6, 'qcm', 'La dernière phrase montre que…', '{"options":["l''espace de travail ferme le vendredi","les chasseurs ont appris l''informatique","les deux groupes se rencontrent maintenant"]}'::jsonb, '{"answer":2}'::jsonb, '« on y croise désormais autant de chasseurs que de développeurs ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce19qun05o', 'practice', 'Lecture B1 : pourtant, cependant', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions.</p>', '<p><strong>Le premier marathon de Léa</strong></p><p>Léa n''avait jamais couru plus de dix kilomètres. Pourtant, en janvier, elle s''est inscrite au marathon de Paris.</p><p>Au début, l''entraînement était difficile. Elle courait trois fois par semaine, malgré le froid et la fatigue. Ses amis lui conseillaient d''abandonner ; elle, au contraire, augmentait chaque semaine la distance.</p><p>En mars, une blessure au genou l''a obligée à s''arrêter quinze jours. Elle aurait pu renoncer. Cependant, elle a profité de cette pause pour nager et faire du vélo, deux sports qui ménagent les articulations.</p><p>Le jour de la course, il faisait très chaud. Bien que beaucoup de coureurs aient ralenti, Léa a gardé son rythme. Elle n''a pas battu de record, mais elle a franchi la ligne d''arrivée en 4 heures 30, avec un grand sourire. Certes, elle avait mal aux jambes ; néanmoins, elle pensait déjà au prochain marathon.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• s''inscrire (verbe) : đăng ký\n• une blessure (nom féminin) : chấn thương\n• ménager (verbe) : giữ gìn, không làm hại\n• ralentir (verbe) : chậm lại\n• franchir (verbe) : vượt qua","explications":"• Pourtant, cependant, néanmoins, malgré, bien que: sau những từ này là ý trái với điều ta chờ đợi.\n• Khoanh từ nối khi đọc để thấy tác giả đang đồng ý hay đối lập.","kyNang":"B1-CE-5","vong":"hoc","thuTu":1}'::jsonb, '2026-11-04T00:00:18.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub042', 'b1ce19qun05o', 1, 'qcm', 'Dans le premier paragraphe, « pourtant » montre que l''inscription de Léa est…', '{"options":["obligatoire","logique","surprenante"]}'::jsonb, '{"answer":2}'::jsonb, 'Trước « pourtant » là « n''avait jamais couru plus de dix kilomètres »: đăng ký marathon là điều bất ngờ.'), ('qmw0y9qub043', 'b1ce19qun05o', 2, 'qcm', '« Malgré le froid et la fatigue » signifie que Léa courait…', '{"options":["parce qu''il faisait froid","même s''il faisait froid et qu''elle était fatiguée","seulement quand il faisait beau"]}'::jsonb, '{"answer":1}'::jsonb, 'malgré + danh từ: mặc dù có.'), ('qmw0y9qub044', 'b1ce19qun05o', 3, 'qcm', '« Au contraire » oppose…', '{"options":["le conseil des amis et l''attitude de Léa","le froid et la fatigue","deux semaines d''entraînement"]}'::jsonb, '{"answer":0}'::jsonb, '« ses amis lui conseillaient d''abandonner » đối lập với việc cô « augmentait chaque semaine la distance ».'), ('qmw0y9qub045', 'b1ce19qun05o', 4, 'qcm', 'Après sa blessure, Léa…', '{"options":["a arrêté tout sport","a couru moins vite","a continué le sport autrement"]}'::jsonb, '{"answer":2}'::jsonb, '« elle a profité de cette pause pour nager et faire du vélo ».'), ('qmw0y9qub046', 'b1ce19qun05o', 5, 'qcm', 'Quel mot pourrait remplacer « cependant » sans changer le sens ?', '{"options":["ensuite","pourtant","donc"]}'::jsonb, '{"answer":1}'::jsonb, 'Cả hai đều báo ý ngược: đáng lẽ bỏ cuộc, nhưng cô vẫn tập.'), ('qmw0y9qub047', 'b1ce19qun05o', 6, 'qcm', '« Bien que beaucoup de coureurs aient ralenti » exprime…', '{"options":["une cause","un but","une opposition"]}'::jsonb, '{"answer":2}'::jsonb, 'bien que + subjonctif: mặc dù. Người khác chậm lại, Léa thì không.'), ('qmw0y9qub048', 'b1ce19qun05o', 7, 'qcm', 'Dans la dernière phrase, « certes… néanmoins » sert à…', '{"options":["reconnaître un point négatif, puis dire le contraire","donner deux causes","raconter deux moments"]}'::jsonb, '{"answer":0}'::jsonb, '« certes, elle avait mal aux jambes » rồi « néanmoins, elle pensait déjà au prochain marathon ».'), ('qmw0y9qub049', 'b1ce19qun05o', 8, 'fill', 'Relevez dans le troisième paragraphe le verbe qui signifie « abandonner ».', '{}'::jsonb, '{"accepted":"renoncer"}'::jsonb, '« elle aurait pu renoncer ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce20qun05p', 'practice', 'Lecture B1 : donc, en effet, car', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Pourquoi les librairies résistent</strong></p><p>On annonçait leur disparition il y a vingt ans. Les librairies indépendantes sont pourtant toujours là : en France, on en compte encore environ 3 500. Comment expliquer cette résistance ?</p><p>D''abord, les Français restent attachés au livre papier. En effet, les livres numériques représentent moins de 10 % des ventes. Beaucoup de lecteurs aiment feuilleter un livre avant de l''acheter, car ils veulent juger le style de l''auteur.</p><p>Ensuite, la loi protège les petites librairies. Depuis 1981, le prix d''un livre est le même partout, en ligne comme en magasin. Les grandes plateformes ne peuvent donc pas vendre beaucoup moins cher.</p><p>Enfin, le libraire offre quelque chose qu''aucun algorithme ne remplace : le conseil. Il connaît ses clients, lit les nouveautés et organise des rencontres avec des écrivains. Par conséquent, la librairie devient un lieu de vie, et pas seulement un commerce.</p><p>La situation reste fragile, car les loyers augmentent dans les centres-villes. Mais tant que les lecteurs pousseront la porte, les libraires continueront à se battre.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une librairie (nom féminin) : hiệu sách\n• attaché à (adjectif) : gắn bó với\n• feuilleter (verbe) : lật xem\n• un atout (nom masculin) : thế mạnh\n• un loyer (nom masculin) : tiền thuê","explications":"• En effet, car: giải thích hoặc chứng minh. Donc, par conséquent: kết quả.\n• D''abord, ensuite, enfin cho biết bài có mấy lý do: đếm để không sót ý.","isPremium":true,"price":19000,"kyNang":"B1-CE-5","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T00:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub04a', 'b1ce20qun05p', 1, 'qcm', 'Dans le deuxième paragraphe, « en effet » introduit…', '{"options":["une conséquence","une opposition","une preuve de l''idée précédente"]}'::jsonb, '{"answer":2}'::jsonb, 'Ý trước: người Pháp gắn bó với sách giấy. Bằng chứng: « les livres numériques représentent moins de 10 % des ventes ».'), ('qmw0y9qub04b', 'b1ce20qun05p', 2, 'qcm', 'Pourquoi les lecteurs aiment-ils feuilleter un livre ?', '{"options":["Pour payer moins cher.","Pour rencontrer l''écrivain.","Pour juger le style de l''auteur."]}'::jsonb, '{"answer":2}'::jsonb, '« car ils veulent juger le style de l''auteur »: car nêu lý do.'), ('qmw0y9qub04c', 'b1ce20qun05p', 3, 'qcm', 'Dans « les grandes plateformes ne peuvent donc pas vendre beaucoup moins cher », « donc » annonce…', '{"options":["un exemple","une conséquence de la loi","une cause"]}'::jsonb, '{"answer":1}'::jsonb, 'Vì « le prix d''un livre est le même partout » nên các nền tảng lớn không bán rẻ hơn được.'), ('qmw0y9qub04d', 'b1ce20qun05p', 4, 'qcm', 'Pourquoi le prix d''un livre est-il le même partout ?', '{"options":["Grâce aux plateformes en ligne.","À cause d''une loi de 1981.","Parce que les libraires se sont mis d''accord."]}'::jsonb, '{"answer":1}'::jsonb, '« depuis 1981, le prix d''un livre est le même partout ».'), ('qmw0y9qub04e', 'b1ce20qun05p', 5, 'qcm', 'Quelle expression pourrait remplacer « par conséquent » ?', '{"options":["c''est pourquoi","parce que","pourtant"]}'::jsonb, '{"answer":0}'::jsonb, 'Par conséquent nêu kết quả, giống c''est pourquoi. Parce que nêu nguyên nhân.'), ('qmw0y9qub04f', 'b1ce20qun05p', 6, 'qcm', 'D''après l''article, le principal atout du libraire est…', '{"options":["le conseil personnalisé","le prix bas","la livraison rapide"]}'::jsonb, '{"answer":0}'::jsonb, '« quelque chose qu''aucun algorithme ne remplace : le conseil ».'), ('qmw0y9qub04g', 'b1ce20qun05p', 7, 'qcm', 'Dans le dernier paragraphe, « car les loyers augmentent » explique…', '{"options":["pourquoi les lecteurs viennent","pourquoi la situation reste fragile","pourquoi les librairies ont disparu"]}'::jsonb, '{"answer":1}'::jsonb, '« la situation reste fragile, car les loyers augmentent ».'), ('qmw0y9qub04h', 'b1ce20qun05p', 8, 'qcm', 'Les mots « d''abord », « ensuite », « enfin » servent à…', '{"options":["raconter une histoire","opposer deux idées","présenter plusieurs raisons dans l''ordre"]}'::jsonb, '{"answer":2}'::jsonb, 'Bài trả lời câu hỏi « comment expliquer cette résistance ? » bằng ba lý do.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce21qun05q', 'practice', 'Lecture B1 : le fil de l''article', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Faut-il en finir avec les devoirs à la maison ?</strong></p><p>Chaque soir, dans des milliers de foyers, la même scène se répète : un enfant fatigué devant son cahier, un parent qui s''énerve, et des exercices qui durent parfois plus d''une heure. Officiellement, pourtant, les devoirs écrits sont interdits à l''école primaire en France depuis 1956.</p><p>Pour leurs défenseurs, les devoirs sont indispensables. Ils permettent de revoir les leçons, de prendre de bonnes habitudes de travail et de montrer aux parents ce qui se fait en classe.</p><p>Leurs adversaires répondent qu''ils creusent les inégalités. Un enfant dont les parents ont le temps et les connaissances pour l''aider avance plus vite ; un autre, seul à la maison, prend du retard. Plusieurs études montrent d''ailleurs que les devoirs ont peu d''effet sur les résultats avant le collège.</p><p>Entre ces deux positions, des écoles cherchent une voie moyenne. Certaines proposent une heure d''aide aux devoirs après la classe, encadrée par des enseignants. Les élèves rentrent chez eux le travail terminé, et la soirée en famille redevient un moment calme.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un foyer (nom masculin) : gia đình, tổ ấm\n• un défenseur (nom masculin) : người ủng hộ\n• un adversaire (nom masculin) : người phản đối\n• creuser les inégalités (expression) : làm sâu thêm bất bình đẳng\n• encadré (adjectif) : có người hướng dẫn","explications":"• Bài nghị luận B1 hay theo khuôn: tình huống, ý kiến ủng hộ, ý kiến phản đối, giải pháp.\n• Câu đầu mỗi đoạn cho biết vai trò của đoạn: « pour leurs défenseurs », « leurs adversaires ».","isPremium":true,"price":19000,"kyNang":"B1-CE-5","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T00:00:20.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9qub04i', 'b1ce21qun05q', 1, 'qcm', 'Le premier paragraphe sert à…', '{"options":["présenter la situation et le problème","donner l''avis de l''auteur","proposer une solution"]}'::jsonb, '{"answer":0}'::jsonb, 'Tả cảnh tối nào cũng lặp lại, rồi nêu nghịch lý: « les devoirs écrits sont interdits à l''école primaire ».'), ('qmw0y9qub04j', 'b1ce21qun05q', 2, 'qcm', 'Le deuxième paragraphe présente…', '{"options":["une étude scientifique","les arguments contre les devoirs","les arguments pour les devoirs"]}'::jsonb, '{"answer":2}'::jsonb, '« pour leurs défenseurs, les devoirs sont indispensables ».'), ('qmw0y9qub04k', 'b1ce21qun05q', 3, 'qcm', 'Le troisième paragraphe présente…', '{"options":["l''histoire d''une loi","les arguments contre les devoirs","l''avis des enseignants"]}'::jsonb, '{"answer":1}'::jsonb, '« leurs adversaires répondent qu''ils creusent les inégalités ».'), ('qmw0y9qub04l', 'b1ce21qun05q', 4, 'qcm', 'Dans le troisième paragraphe, « d''ailleurs » sert à…', '{"options":["conclure l''article","introduire une opposition","ajouter un argument qui renforce l''idée"]}'::jsonb, '{"answer":2}'::jsonb, 'Sau bất bình đẳng, thêm bằng chứng cùng hướng: « les devoirs ont peu d''effet sur les résultats ».'), ('qmw0y9qub04m', 'b1ce21qun05q', 5, 'qcm', 'Le dernier paragraphe…', '{"options":["raconte l''histoire des devoirs","rejette les deux positions","propose un compromis"]}'::jsonb, '{"answer":2}'::jsonb, '« des écoles cherchent une voie moyenne ».'), ('qmw0y9qub04n', 'b1ce21qun05q', 6, 'ordre', 'Remettez dans l''ordre les quatre étapes de l''article.', '{"elements":[{"id":"emw0y9quc04q","texte":"Les arguments contre"},{"id":"emw0y9quc04r","texte":"Une solution intermédiaire"},{"id":"emw0y9qub04o","texte":"Une scène de tous les jours"},{"id":"emw0y9quc04p","texte":"Les arguments pour"}]}'::jsonb, '{"elements":[{"id":"emw0y9qub04o","texte":"Une scène de tous les jours"},{"id":"emw0y9quc04p","texte":"Les arguments pour"},{"id":"emw0y9quc04q","texte":"Les arguments contre"},{"id":"emw0y9quc04r","texte":"Une solution intermédiaire"}]}'::jsonb, 'Bài đi từ tình huống, sang hai phía tranh luận, rồi tới giải pháp ở giữa: « une voie moyenne ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce22quo05r', 'practice', 'Lecture B1 : le mot manquant', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article et choisissez le mot qui manque, puis répondez aux questions.</p>', '<p><strong>Covoiturer pour aller au travail</strong></p><p>Chaque matin, des millions de Français prennent leur voiture seuls pour aller travailler. (1) ______, le covoiturage reste rare sur ces trajets quotidiens, (2) ______ il permettrait d''économiser de l''argent et de réduire les embouteillages.</p><p>Pourquoi cette réticence ? (3) ______, les horaires de travail sont de plus en plus variables, ce qui rend l''organisation difficile. (4) ______, beaucoup de conducteurs tiennent à leur liberté : ils veulent pouvoir partir quand ils le souhaitent.</p><p>Pour changer les habitudes, certaines régions offrent des trajets gratuits aux passagers. (5) ______, en Occitanie, un passager ne paie rien et le conducteur reçoit deux euros par trajet. Les résultats sont encourageants : le nombre de covoitureurs a doublé en un an. (6) ______, ces aides coûtent cher, et on ne sait pas si les habitudes resteront quand elles s''arrêteront.</p><p>(7) ______, le covoiturage ne remplacera pas les transports en commun. Il peut (8) ______ être une solution utile dans les zones rurales, où les bus sont rares.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le covoiturage (nom masculin) : đi chung xe\n• un embouteillage (nom masculin) : tắc đường\n• la réticence (nom féminin) : sự ngần ngại\n• tenir à (verbe) : coi trọng, muốn giữ\n• rural (adjectif) : thuộc nông thôn","explications":"• Đọc cả câu trước và câu sau chỗ trống, hỏi: hai ý cùng hướng, ngược hướng, hay là ví dụ?\n• Phương án sai ngữ pháp (« Il peut car être ») loại ngay.","isPremium":true,"price":19000,"kyNang":"B1-CE-5","vong":"on","thuTu":4}'::jsonb, '2026-11-04T00:00:21.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9quc04s', 'b1ce22quo05r', 1, 'qcm', 'Mot manquant (1) :', '{"options":["Pourtant","Donc","Par exemple"]}'::jsonb, '{"answer":0}'::jsonb, 'Nhiều người đi xe một mình, vậy mà đi chung xe vẫn hiếm: ý ngược với điều chờ đợi.'), ('qmw0y9quc04t', 'b1ce22quo05r', 2, 'qcm', 'Mot manquant (2) :', '{"options":["alors qu''","afin qu''","parce qu''"]}'::jsonb, '{"answer":0}'::jsonb, 'Đi chung xe hiếm, trong khi nó có lợi: alors que nêu sự tương phản.'), ('qmw0y9quc04u', 'b1ce22quo05r', 3, 'qcm', 'Mot manquant (3) :', '{"options":["Donc","Pourtant","D''abord"]}'::jsonb, '{"answer":2}'::jsonb, '« pourquoi cette réticence ? » rồi kể lý do thứ nhất.'), ('qmw0y9quc04v', 'b1ce22quo05r', 4, 'qcm', 'Mot manquant (4) :', '{"options":["Car","Au contraire","Ensuite"]}'::jsonb, '{"answer":2}'::jsonb, 'Lý do thứ hai, tiếp sau lý do thứ nhất.'), ('qmw0y9quc04w', 'b1ce22quo05r', 5, 'qcm', 'Mot manquant (5) :', '{"options":["Donc","Cependant","Par exemple"]}'::jsonb, '{"answer":2}'::jsonb, 'Vùng Occitanie là ví dụ cho « certaines régions ».'), ('qmw0y9quc04x', 'b1ce22quo05r', 6, 'qcm', 'Mot manquant (6) :', '{"options":["En effet","Ainsi","Cependant"]}'::jsonb, '{"answer":2}'::jsonb, 'Sau kết quả tốt là mặt hạn chế: « ces aides coûtent cher ».'), ('qmw0y9quc04y', 'b1ce22quo05r', 7, 'qcm', 'Mot manquant (7) :', '{"options":["Bien sûr","Parce que","Par exemple"]}'::jsonb, '{"answer":0}'::jsonb, 'Tác giả thừa nhận một giới hạn trước khi nêu ích lợi ở câu sau.'), ('qmw0y9quc04z', 'b1ce22quo05r', 8, 'qcm', 'Mot manquant (8) :', '{"options":["en revanche","car","ensuite"]}'::jsonb, '{"answer":0}'::jsonb, 'Không thay được giao thông công cộng, ngược lại vẫn hữu ích ở nông thôn.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1ce23quo05s', 'practice', 'Lecture B1 : que fait l''auteur ?', 'B1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cet article, puis répondez aux questions.</p>', '<p><strong>Trop de touristes ? Mieux vaut les répartir</strong></p><p>Venise, Barcelone, le Mont-Saint-Michel : chaque été, les mêmes images de foules montrent des rues bloquées et des habitants exaspérés. Le tourisme de masse est devenu un sujet de débat dans toute l''Europe.</p><p>Il serait pourtant injuste de condamner les touristes. Dans de nombreuses régions, ils font vivre les hôtels, les restaurants et les commerces. Sans eux, des milliers d''emplois disparaîtraient.</p><p>Le problème ne vient donc pas du nombre total de visiteurs, mais de leur concentration. Les trois quarts se pressent dans les mêmes lieux, aux mêmes semaines. Quelques kilomètres plus loin, des villages magnifiques restent presque vides.</p><p>Certaines villes ont choisi la manière forte : Venise fait payer l''entrée aux visiteurs d''un jour, Amsterdam limite les nouveaux hôtels. D''autres préfèrent encourager les voyageurs à venir hors saison ou à découvrir d''autres quartiers.</p><p>À mon avis, la seconde voie est la plus prometteuse. Interdire risque de réserver les plus beaux lieux aux plus riches ; mieux répartir les touristes profite à tous, habitants comme visiteurs.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• exaspéré (adjectif) : bực tức cực độ\n• condamner (verbe) : lên án\n• la concentration (nom féminin) : sự dồn vào một chỗ\n• hors saison (expression) : ngoài mùa cao điểm\n• prometteur (adjectif) : đầy hứa hẹn","explications":"• Ý kiến của tác giả thường xuất hiện ở cuối, sau « à mon avis ».\n• Hỏi « que fait l''auteur ? »: trả lời bằng động từ (présenter, nuancer, comparer, conclure).","isPremium":true,"price":19000,"kyNang":"B1-CE-5","vong":"chot","thuTu":5}'::jsonb, '2026-11-04T00:00:22.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw0y9quc050', 'b1ce23quo05s', 1, 'qcm', 'Dans le premier paragraphe, l''auteur…', '{"options":["critique les habitants","présente un problème actuel","donne son opinion"]}'::jsonb, '{"answer":1}'::jsonb, '« le tourisme de masse est devenu un sujet de débat dans toute l''Europe ».'), ('qmw0y9quc051', 'b1ce23quo05s', 2, 'qcm', 'Au début du deuxième paragraphe, l''auteur…', '{"options":["accuse les touristes","change de sujet","nuance la critique contre les touristes"]}'::jsonb, '{"answer":2}'::jsonb, '« il serait pourtant injuste de condamner les touristes ».'), ('qmw0y9quc052', 'b1ce23quo05s', 3, 'qcm', 'Dans le troisième paragraphe, « donc » introduit…', '{"options":["un exemple","une conclusion tirée de ce qui précède","une opposition"]}'::jsonb, '{"answer":1}'::jsonb, 'Khách du lịch có ích (đoạn 2), vậy vấn đề không nằm ở số lượng: « le problème ne vient donc pas du nombre total de visiteurs ».'), ('qmw0y9quc053', 'b1ce23quo05s', 4, 'qcm', 'Selon l''auteur, le vrai problème est que les touristes…', '{"options":["vont tous aux mêmes endroits","sont trop nombreux","dépensent peu"]}'::jsonb, '{"answer":0}'::jsonb, '« mais de leur concentration », « dans les mêmes lieux, aux mêmes semaines ».'), ('qmw0y9quc054', 'b1ce23quo05s', 5, 'qcm', 'Le quatrième paragraphe…', '{"options":["donne des chiffres sur l''emploi","raconte un voyage","compare deux types de solutions"]}'::jsonb, '{"answer":2}'::jsonb, '« certaines villes ont choisi la manière forte » và « d''autres préfèrent encourager ».'), ('qmw0y9quc055', 'b1ce23quo05s', 6, 'qcm', 'Que pense l''auteur des solutions qui interdisent ou font payer ?', '{"options":["Elles profitent à tous.","Ce sont les meilleures solutions.","Elles peuvent être injustes pour les moins riches."]}'::jsonb, '{"answer":2}'::jsonb, '« interdire risque de réserver les plus beaux lieux aux plus riches ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

do $$
declare b int; c int;
begin
  select count(*) into b from public.exercises where id like 'b1ce%';
  select count(*) into c from public.questions where exercise_id like 'b1ce%';
  if b <> 23 or c <> 139 then raise exception 'lô 36: % bài, % câu (cần 23, 139)', b, c; end if;
end $$;
